head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/bns_common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/list_common.js");
scwin.vScrenID = 'ULDBNS90008.xml';
scwin.vMktactCd = '320'; //채권시장조치구분코드
scwin.pBndApplId = '', scwin.pStrtDd = '', scwin.pIsuCd = '';
scwin.vBndListProcsTpCd = 1; //채권처리구분(1:신청,2:접수)
scwin.vDtlInfoRowCount = 0;
scwin.arrPar = new Array();
scwin.fn_GetPar, scwin.fn_SetPar;
scwin.vViewYN = 'Y';
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};

/********************************************** 
 * 함수명   : fn_SetParam
 * 설명       : 부모창에서 받은 데이터를 설정한다.
 ***********************************************/
scwin.fn_SetParam = function() {
    var prt = $c.frame.path("../");
    if (prt != undefined) {
        scwin.fn_GetPar = prt.scwin.fn_GetPar;
        scwin.fn_SetPar = prt.scwin.fn_SetPar;
    }
    if (scwin.fn_GetPar != undefined) {
        scwin.fn_GetPar(scwin.arrPar);
        scwin.pBndApplId = scwin.arrPar[0].BND_APPL_ID;
        scwin.pIsuCd = scwin.arrPar[0].STD_CD;
        scwin.pStrtDd = scwin.arrPar[0].STRT_DD;
    }
};



/********************************************** 
 * 함수명  	 : fn_dtl_sync
 * 설명       : 상세조회
 ***********************************************/
scwin.fn_dtl_sync = function() {
    var dsNm = 'BNS_ISU_CHG_INFO';
    var qryId = '';
    var param = '';
    if (scwin.vBndListProcsTpCd == 1) {
        qryId = 'lds.stf.bnsisuchg.select.readIsuChgInfoAmtMmDdAdd';
        param += '&{P}V_MKTACT_CD=' + scwin.vMktactCd;
        param += '&{P}V_BND_APPL_ID=' + scwin.pBndApplId;
        param += '&{P}V_VIEW_YN=' + scwin.vViewYN;
    }
    if (scwin.vBndListProcsTpCd == 2) {
        qryId = 'lds.stf.bnsisuchg.select.readIsuChgInfoAmtDdAppl';
        param += '&{P}V_ISU_CD=' + scwin.pIsuCd;
        param += '&{P}V_STRT_DD=' + scwin.pStrtDd;
    }
    param += '&{P}V_BND_LIST_PROCS_TP_CD=' + scwin.vBndListProcsTpCd;
    $c.bns.fn_SearchBns(scwin.vScrenID, dts_DtlInfo, dsNm, qryId, param);
};


/********************************************** 
 * 함수명  	 : fn_sales_sync
 * 설명       : 매출기관별 매출내역 조회
 ***********************************************/
scwin.fn_sales_sync = function() {
    var dsNm = 'BNS_SALES_DESC';
    var qryId = 'lds.stf.bnsisuchg.select.listSalesDesc';
    var param = '&{P}V_BND_LIST_PROCS_TP_CD=' + scwin.vBndListProcsTpCd;
    param += '&{P}V_ISU_CD=' + scwin.pIsuCd;
    param += '&{P}V_STRT_DD=' + scwin.pStrtDd;
    $c.bns.fn_SearchBns(scwin.vScrenID, dts_SalesList, dsNm, qryId, param);
};


/********************************************** 
 * 함수명   : fn_GetCommonKey
 * 설명       : 팝업에 넘길 키데이터를 정의한다.
 ***********************************************/
scwin.fn_GetCommonKey = function(arrPar) {
    var vBndApplId = '';
    if (scwin.vBndListProcsTpCd == 1) {
        vBndApplId = dts_DtlInfo.getCellData(1, "BND_APPL_ID");
    } else {
        vBndApplId = scwin.pBndApplId;
    }
    scwin.arrPar[0] = {
        //첨부문서 목록 팝업	
        BND_APPL_ID: vBndApplId,
        BND_LIST_PROCS_TP_CD: dts_DtlInfo.getCellData(1, "BND_LIST_PROCS_TP_CD"),
        ISU_CD: dts_DtlInfo.getCellData(1, "ISU_CD")
    };
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************
    scwin.arrPar, length;
};


/******************************************************** 
 * 함수명   : fn_GetParIsuDelInfo
 * 설명       : 종목상세/매출통보내역 팝업에 넘길 데이터를 정의한다.
 *********************************************************/
scwin.fn_GetParIsuDelInfo = function(arrPar) {
    scwin.arrPar[0] = {
        STD_CD: dts_DtlInfo.getCellData(1, "ISU_CD"),
        STRT_DD: dts_DtlInfo.getCellData(1, "STRT_DD"),
        BND_LIST_PROCS_TP_CD: scwin.vBndListProcsTpCd
    };
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************
    scwin.arrPar, length;
};
scwin.gform_onload = function() {
    $c.bns.BnsPanelToGroupBox(pnl_Req); //패널라운드처리(신청)
    $c.bns.BnsPanelToGroupBox(pnl_DtlInfo_Req); //패널라운드처리(신청상세)
    $c.bns.BnsPanelToGroupBox(pnl_Acpt); //패널라운드처리(접수)
    $c.bns.BnsPanelToGroupBox(pnl_DtlInfo_Acpt); //패널라운드처리(접수상세)
    $c.bns.BnsPanelToGroupBox(pnl_IsuSales); //패널라운드처리(종목일별 매출내역)

    tab_List.setSelectedTabIndex(1);
    scwin.fn_SetParam(); //호출파라미터설정	
    scwin.fn_dtl_sync(); //상세조회

};
scwin.tab_List_OnSelChanged = function(nIndex) {
    scwin.vBndListProcsTpCd = nIndex;
    scwin.fn_dtl_sync(); //상세조회

};
scwin.dts_DtlInfo_OnLoadCompleted = function(rowcount) {
    scwin.vDtlInfoRowCount = rowcount;
    if (scwin.vBndListProcsTpCd == 2) {
        scwin.fn_sales_sync(); //매출기관별 매출내역 조회

    }

    //매출초일여부 체크 설정
    if (dts_DtlInfo.getCellData(1, "FST_SALE_DD_YN") == 'Y') {
        chk_FstSaleDdYn.setValue(1);
    } else {
        chk_FstSaleDdYn.setValue(0);
    }
    edt_BfchgListAmt.RightMargin = 5;
    edt_BndSaleTotamt.RightMargin = 5;
    edt_RedmptAmt.RightMargin = 5;
    edt_NetSaleAmt.RightMargin = 5;
    edt_IsuAmt.RightMargin = 5;
    edt_CoupnRt.RightMargin = 5;
    edt_BfchgListAmt2.RightMargin = 5;
    edt_NetSaleAmt2.RightMargin = 5;
    edt_AfchgListAmt.RightMargin = 5;
};
scwin.img_StrtDd_onclick = function() {
    if (scwin.vDtlInfoRowCount == 0) return;
    popUpCalendar2(edt_StrtDd);
};
scwin.img_StrtDd2_onclick = function() {
    if (scwin.vDtlInfoRowCount == 0) return;
    popUpCalendar2(edt_StrtDd2);
};
scwin.btn_Attach_onclick = function() {
    if (scwin.vDtlInfoRowCount == 0) return;
    if ("N" == dts_DtlInfo.getCellData(1, "HAS_ATTACH_DOC")) {
        $c.win.alert("연결된 팩스/첨부문서가 없습니다.");
        return;
    }
    scwin.fn_GetPar = fn_GetCommonKey;
    $c.bns.fn_PopAttachDocSearch(lbl_BndApplId);
};
scwin.btn_Attach2_onclick = function() {
    if (scwin.vDtlInfoRowCount == 0) return;
    if ("N" == dts_SalesList.getCellData(dts_SalesList.getRowPosition(), "HAS_ATTACH_DOC")) {
        $c.win.alert("연결된 팩스/첨부문서가 없습니다.");
        return;
    }
    scwin.fn_GetPar = fn_GetCommonKey;
    $c.bns.fn_PopAttachDocSearch(lbl_BndApplId);
};
scwin.btn_Dtl_onclick = function() {
    if (scwin.vDtlInfoRowCount == 0) return;
    scwin.fn_GetPar = fn_GetParIsuDelInfo;
    $c.bns.fn_PopIsuDetail(lbl_BndApplId);
};
scwin.btn_Dtl2_onclick = function() {
    if (scwin.vDtlInfoRowCount == 0) return;
    scwin.fn_GetPar = fn_GetParIsuDelInfo;
    $c.bns.fn_PopIsuDetail(lbl_BndApplId);
};
scwin.btn_Noti_onclick = function() {
    if (scwin.vDtlInfoRowCount == 0) return;
    scwin.fn_GetPar = fn_GetParIsuDelInfo;
    $c.bns.fn_PopSalesNotiList(lbl_BndApplId);
};
scwin.btn_Noti2_onclick = function() {
    if (scwin.vDtlInfoRowCount == 0) return;
    scwin.fn_GetPar = fn_GetParIsuDelInfo;
    $c.bns.fn_PopSalesNotiList(lbl_BndApplId);
};
scwin.btn_Close_onclick = async function() {
    await $c.frame.CloseFrame();
};
scwin.btn_Close2_onclick = async function() {
    await $c.frame.CloseFrame();
};
scwin.img_Saledd_onclick = function() {
    if (scwin.vDtlInfoRowCount == 0) return;
    popUpCalendar2(edt_SaleDd);
};
scwin.edt_BfchgListAmt_OnKillFocus = function() {
    edt_BfchgListAmt.RightMargin = 5;
};
scwin.edt_BndSaleTotamt_OnKillFocus = function() {
    edt_BndSaleTotamt.RightMargin = 5;
};
scwin.edt_RedmptAmt_OnKillFocus = function() {
    edt_RedmptAmt.RightMargin = 5;
};
scwin.edt_NetSaleAmt_OnKillFocus = function() {
    edt_NetSaleAmt.RightMargin = 5;
};
scwin.edt_IsuAmt_OnKillFocus = function() {
    edt_IsuAmt.RightMargin = 5;
};
scwin.edt_CoupnRt_OnKillFocus = function() {
    edt_CoupnRt.RightMargin = 5;
};
scwin.edt_BfchgListAmt2_OnKillFocus = function() {
    edt_BfchgListAmt2.RightMargin = 5;
};
scwin.edt_NetSaleAmt2_OnKillFocus = function() {
    edt_NetSaleAmt2.RightMargin = 5;
};
scwin.edt_AfchgListAmt_OnKillFocus = function() {
    edt_AfchgListAmt.RightMargin = 5;
};
scwin.dts_DtlInfo_OnColumnChanged = function(row, colid) {
    if (colid == "BND_SALE_TOTAMT" || colid == "REDMPT_AMT") {
        /** 일중 순매출액(화면 자동 계산) */
        if (scwin.vBndListProcsTpCd == 1) {
            $c.stf.setObjectValue(edt_NetSaleAmt, Number($c.stf.getObjectValue(edt_BndSaleTotamt)) - Number($c.stf.getObjectValue(edt_RedmptAmt)));
        }
    }
};
